-- RAJAB FINANCE. Money = integer kopecks; no client-side financial writes.
create schema if not exists private;
revoke create on schema public from public;
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id), display_name text not null, platform_admin boolean not null default false);
create table public.organization_members (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), user_id uuid not null references auth.users(id), role text not null check(role in ('owner','manager','cashier','client')), active boolean not null default true, unique(user_id), unique(tenant_id,id));
create table public.customers (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), auth_user_id uuid references auth.users(id), name text not null check(length(name) between 2 and 120), phone text not null, email text, notes text not null default '', created_at timestamptz not null default now(), unique(tenant_id,id), unique(auth_user_id));
create table public.suppliers (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), name text not null, url text, unique(tenant_id,id));
create table public.products (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), name text not null, url text, unique(tenant_id,id));
create table public.organization_settings (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), version int not null check(version>0), mode text not null check(mode in ('fixed','term','individual')), fixed_bps int not null check(fixed_bps between 0 and 100000), term_rates jsonb not null, prevent_negative_cash boolean not null default true, created_by uuid references auth.users(id), created_at timestamptz not null default now(), unique(tenant_id,version), unique(tenant_id,id));
create table public.applications (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), customer_id uuid not null, product_name text not null, product_url text, supplier text not null default '', estimated_cost bigint not null check(estimated_cost>0 and estimated_cost<=100000000000), down_payment bigint not null default 0 check(down_payment>=0), months int not null check(months between 1 and 36), notes text not null default '', status text not null default 'review' check(status in ('draft','review','approved','rejected','awaiting_purchase','purchased','ready_to_sell','contracted')), final_quote jsonb, created_by uuid references auth.users(id), created_at timestamptz not null default now(), unique(tenant_id,id), foreign key(tenant_id,customer_id) references public.customers(tenant_id,id));
create table public.documents (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), application_id uuid, kind text not null check(kind in ('purchase_receipt','ownership','transfer')), name text not null, storage_path text not null unique, mime_type text not null check(mime_type in ('application/pdf','image/png','image/jpeg')), size_bytes int not null check(size_bytes between 1 and 5242880), sha256 text not null check(length(sha256)=64), created_by uuid references auth.users(id), created_at timestamptz not null default now(), unique(tenant_id,id), foreign key(tenant_id,application_id) references public.applications(tenant_id,id));
create table public.purchases (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), application_id uuid not null, supplier text not null, cost bigint not null check(cost>0 and cost<=100000000000), purchased_on date not null, ownership_confirmed boolean not null check(ownership_confirmed), document_id uuid not null, created_by uuid references auth.users(id), created_at timestamptz not null default now(), unique(tenant_id,id), unique(tenant_id,application_id), foreign key(tenant_id,application_id) references public.applications(tenant_id,id), foreign key(tenant_id,document_id) references public.documents(tenant_id,id));
create table public.document_templates (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), version int not null, name text not null, body jsonb not null default '{}', approved boolean not null default false check(approved=false), unique(tenant_id,id), unique(tenant_id,version));
create table public.contracts (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), customer_id uuid not null, application_id uuid not null, purchase_id uuid not null, number text not null, signed_on date not null, cost bigint not null check(cost>0), profit bigint not null check(profit>=0), sale_price bigint not null check(sale_price=cost+profit), down_payment bigint not null check(down_payment>=0 and down_payment<=sale_price), months int not null check(months between 1 and 36), first_payment_on date not null, status text not null default 'signed' check(status in ('signed','transferred','closed')), transferred_on date, transfer_reference text, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), unique(tenant_id,id), unique(tenant_id,number), unique(tenant_id,application_id), foreign key(tenant_id,customer_id) references public.customers(tenant_id,id), foreign key(tenant_id,application_id) references public.applications(tenant_id,id), foreign key(tenant_id,purchase_id) references public.purchases(tenant_id,id));
create table public.contract_items (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), contract_id uuid not null, product_name text not null, product_url text, cost bigint not null, unique(tenant_id,id), foreign key(tenant_id,contract_id) references public.contracts(tenant_id,id));
create table public.contract_versions (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), contract_id uuid not null, version int not null default 1, snapshot jsonb not null, created_at timestamptz not null default now(), unique(tenant_id,id), unique(tenant_id,contract_id,version), foreign key(tenant_id,contract_id) references public.contracts(tenant_id,id));
create table public.payment_schedules (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), contract_id uuid not null, sequence int not null check(sequence>=0), due_on date not null, amount bigint not null check(amount>0), unique(tenant_id,id), unique(tenant_id,contract_id,sequence), foreign key(tenant_id,contract_id) references public.contracts(tenant_id,id));
create table public.cash_accounts (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), name text not null, unique(tenant_id,id));
create table public.payments (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), contract_id uuid not null, cash_account_id uuid not null, amount bigint not null check(amount<>0), reversal_of uuid, reason text not null default '', operation_key uuid not null, paid_on date not null, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), unique(tenant_id,id), unique(tenant_id,operation_key), unique(tenant_id,reversal_of), foreign key(tenant_id,contract_id) references public.contracts(tenant_id,id), foreign key(tenant_id,cash_account_id) references public.cash_accounts(tenant_id,id), foreign key(tenant_id,reversal_of) references public.payments(tenant_id,id), check((amount>0 and reversal_of is null) or (amount<0 and reversal_of is not null)));
create table public.payment_allocations (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), payment_id uuid not null, schedule_id uuid not null, amount bigint not null check(amount<>0), unique(tenant_id,id), unique(tenant_id,payment_id,schedule_id), foreign key(tenant_id,payment_id) references public.payments(tenant_id,id), foreign key(tenant_id,schedule_id) references public.payment_schedules(tenant_id,id));
create table public.cash_transactions (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), cash_account_id uuid not null, payment_id uuid, amount bigint not null check(amount<>0), operation_key uuid not null, kind text not null check(kind in ('payment','reversal','income','expense','transfer')), description text not null, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), unique(tenant_id,id), unique(tenant_id,operation_key,cash_account_id), foreign key(tenant_id,cash_account_id) references public.cash_accounts(tenant_id,id), foreign key(tenant_id,payment_id) references public.payments(tenant_id,id));
create table public.notifications (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), kind text not null, dedupe_key text not null, message text not null, status text not null default 'pending' check(status in ('pending','sending','sent','failed')), attempts int not null default 0, last_error text, locked_at timestamptz, created_at timestamptz not null default now(), sent_at timestamptz, unique(tenant_id,id), unique(tenant_id,dedupe_key));
create table public.audit_logs (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), actor_id uuid references auth.users(id), action text not null, entity_id uuid, details jsonb not null default '{}', created_at timestamptz not null default now(), unique(tenant_id,id));
create table public.operations (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), operation_key uuid not null, action text not null, payload jsonb not null, result jsonb not null, actor_id uuid references auth.users(id), unique(tenant_id,operation_key));
create table public.subscription_plans (id uuid primary key default gen_random_uuid(), name text not null, employee_limit int not null, contract_limit int not null);
create table public.subscriptions (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.organizations(id), plan_id uuid not null references public.subscription_plans(id), status text not null default 'trial', unique(tenant_id,id));
create table private.rate_limits (key text primary key, window_start timestamptz not null, hits int not null);

create function private.current_tenant() returns uuid language sql stable security definer set search_path='' as $$select tenant_id from public.organization_members where user_id=auth.uid() and active limit 1$$;
create function private.current_role() returns text language sql stable security definer set search_path='' as $$select role from public.organization_members where user_id=auth.uid() and active limit 1$$;
create function private.staff(t uuid, roles text[] default array['owner','manager','cashier']) returns boolean language sql stable security definer set search_path='' as $$select coalesce(t=private.current_tenant() and private.current_role()=any(roles),false)$$;
create function private.own_contract(t uuid,c uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.contracts k join public.customers u on u.id=k.customer_id and u.tenant_id=k.tenant_id where k.id=c and k.tenant_id=t and u.auth_user_id=auth.uid() and t=private.current_tenant() and private.current_role()='client')$$;
create function private.platform_admin() returns boolean language sql stable security definer set search_path='' as $$select coalesce((select platform_admin from public.profiles where id=auth.uid()),false)$$;
create function private.immutable() returns trigger language plpgsql as $$begin raise exception 'Запись неизменяема. Используйте отдельную корректирующую операцию.'; end$$;
create function private.contract_guard() returns trigger language plpgsql as $$begin if (to_jsonb(new)-array['status','transferred_on','transfer_reference']) is distinct from (to_jsonb(old)-array['status','transferred_on','transfer_reference']) then raise exception 'Цена и условия заключённого договора неизменяемы'; end if; return new; end$$;
create trigger contract_snapshot_guard before update on public.contracts for each row execute function private.contract_guard();
create index organization_members_tenant_idx on public.organization_members(tenant_id);
alter table public.organization_members enable row level security;
create index customers_tenant_idx on public.customers(tenant_id);
alter table public.customers enable row level security;
create index suppliers_tenant_idx on public.suppliers(tenant_id);
alter table public.suppliers enable row level security;
create index products_tenant_idx on public.products(tenant_id);
alter table public.products enable row level security;
create index organization_settings_tenant_idx on public.organization_settings(tenant_id);
alter table public.organization_settings enable row level security;
create index applications_tenant_idx on public.applications(tenant_id);
alter table public.applications enable row level security;
create index documents_tenant_idx on public.documents(tenant_id);
alter table public.documents enable row level security;
create index purchases_tenant_idx on public.purchases(tenant_id);
alter table public.purchases enable row level security;
create index document_templates_tenant_idx on public.document_templates(tenant_id);
alter table public.document_templates enable row level security;
create index contracts_tenant_idx on public.contracts(tenant_id);
alter table public.contracts enable row level security;
create index contract_items_tenant_idx on public.contract_items(tenant_id);
alter table public.contract_items enable row level security;
create index contract_versions_tenant_idx on public.contract_versions(tenant_id);
alter table public.contract_versions enable row level security;
create index payment_schedules_tenant_idx on public.payment_schedules(tenant_id);
alter table public.payment_schedules enable row level security;
create index cash_accounts_tenant_idx on public.cash_accounts(tenant_id);
alter table public.cash_accounts enable row level security;
create index payments_tenant_idx on public.payments(tenant_id);
alter table public.payments enable row level security;
create index payment_allocations_tenant_idx on public.payment_allocations(tenant_id);
alter table public.payment_allocations enable row level security;
create index cash_transactions_tenant_idx on public.cash_transactions(tenant_id);
alter table public.cash_transactions enable row level security;
create index notifications_tenant_idx on public.notifications(tenant_id);
alter table public.notifications enable row level security;
create index audit_logs_tenant_idx on public.audit_logs(tenant_id);
alter table public.audit_logs enable row level security;
create index operations_tenant_idx on public.operations(tenant_id);
alter table public.operations enable row level security;
create index subscriptions_tenant_idx on public.subscriptions(tenant_id);
alter table public.subscriptions enable row level security;
alter table public.organizations enable row level security;
alter table public.profiles enable row level security;
alter table public.subscription_plans enable row level security;
create policy organization_read on public.organizations for select to authenticated using(id=private.current_tenant() or private.platform_admin());
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid());
create policy member_read on public.organization_members for select to authenticated using(user_id=auth.uid() or private.staff(tenant_id,array['owner']));
create policy customers_read on public.customers for select to authenticated using(private.staff(tenant_id,array['owner','manager']) or (tenant_id=private.current_tenant() and auth_user_id=auth.uid()));
create policy suppliers_read on public.suppliers for select to authenticated using(private.staff(tenant_id,array['owner','manager']));
create policy products_read on public.products for select to authenticated using(private.staff(tenant_id,array['owner','manager']));
create policy applications_read on public.applications for select to authenticated using(private.staff(tenant_id,array['owner','manager']));
create policy purchases_read on public.purchases for select to authenticated using(private.staff(tenant_id,array['owner','manager']));
create policy documents_read on public.documents for select to authenticated using(private.staff(tenant_id,array['owner','manager']));
create policy document_templates_read on public.document_templates for select to authenticated using(private.staff(tenant_id,array['owner','manager']));
create policy organization_settings_read on public.organization_settings for select to authenticated using(private.staff(tenant_id,array['owner','manager','cashier']));
create policy audit_logs_read on public.audit_logs for select to authenticated using(private.staff(tenant_id,array['owner']));
create policy notifications_read on public.notifications for select to authenticated using(private.staff(tenant_id,array['owner','manager','cashier']));
create policy contracts_read on public.contracts for select to authenticated using(private.staff(tenant_id) or private.own_contract(tenant_id,id));
create policy contract_items_read on public.contract_items for select to authenticated using(private.staff(tenant_id) or private.own_contract(tenant_id,contract_id));
create policy contract_versions_read on public.contract_versions for select to authenticated using(private.staff(tenant_id) or private.own_contract(tenant_id,contract_id));
create policy payment_schedules_read on public.payment_schedules for select to authenticated using(private.staff(tenant_id) or private.own_contract(tenant_id,contract_id));
create policy payments_read on public.payments for select to authenticated using(private.staff(tenant_id) or private.own_contract(tenant_id,contract_id));
create policy allocations_read on public.payment_allocations for select to authenticated using(private.staff(tenant_id) or exists(select 1 from public.payments p where p.id=payment_id and p.tenant_id=payment_allocations.tenant_id));
create policy cash_accounts_read on public.cash_accounts for select to authenticated using(private.staff(tenant_id,array['owner','cashier']));
create policy cash_transactions_read on public.cash_transactions for select to authenticated using(private.staff(tenant_id,array['owner','cashier']));
create policy subscriptions_read on public.subscriptions for select to authenticated using(private.staff(tenant_id,array['owner']) or private.platform_admin());
create policy plans_read on public.subscription_plans for select to authenticated using(private.current_role()='owner' or private.platform_admin());
create trigger organization_settings_immutable before update or delete on public.organization_settings for each row execute function private.immutable();
create trigger purchases_immutable before update or delete on public.purchases for each row execute function private.immutable();
create trigger documents_immutable before update or delete on public.documents for each row execute function private.immutable();
create trigger contract_items_immutable before update or delete on public.contract_items for each row execute function private.immutable();
create trigger contract_versions_immutable before update or delete on public.contract_versions for each row execute function private.immutable();
create trigger payment_schedules_immutable before update or delete on public.payment_schedules for each row execute function private.immutable();
create trigger payments_immutable before update or delete on public.payments for each row execute function private.immutable();
create trigger payment_allocations_immutable before update or delete on public.payment_allocations for each row execute function private.immutable();
create trigger cash_transactions_immutable before update or delete on public.cash_transactions for each row execute function private.immutable();
create trigger audit_logs_immutable before update or delete on public.audit_logs for each row execute function private.immutable();
create trigger operations_immutable before update or delete on public.operations for each row execute function private.immutable();
create trigger document_templates_immutable before update or delete on public.document_templates for each row execute function private.immutable();
grant usage on schema public,private to authenticated;
grant select on all tables in schema public to authenticated;
revoke all on public.operations from authenticated;
revoke all on all functions in schema private from public;
grant execute on function private.current_tenant(),private.current_role(),private.staff(uuid,text[]),private.own_contract(uuid,uuid),private.platform_admin() to authenticated;
